const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'Gemini CLI';
pres.title = '1,001 Real-World Gen AI Use Cases from Google Cloud Customers';

const C_NAVY = "1E2761";
const C_ICE = "CADCFC";
const C_WHITE = "FFFFFF";
const C_CORAL = "F96167";
const C_LIGHT_BG = "F4F6F9";
const C_DARK_TEXT = "1A1F3B";
const C_MUTED_TEXT = "5A6785";

const FONT_HEAD = "Georgia";
const FONT_BODY = "Calibri";

const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, color: "000000", opacity: 0.1 });

// Helper to add slide title
function addSlideTitle(slide, text, isDark=false) {
    slide.addText(text, {
        x: 0.5, y: 0.4, w: 9.0, h: 0.6,
        fontSize: 24, fontFace: FONT_HEAD, bold: true,
        color: isDark ? C_WHITE : C_NAVY,
        margin: 0
    });
}

// SLIDE 1: Title
let s1 = pres.addSlide();
s1.background = { color: C_NAVY };

s1.addText("1,001", { 
    x: 0.5, y: 1.2, w: 9, h: 1.2, 
    fontSize: 80, fontFace: FONT_HEAD, color: C_CORAL, bold: true, margin: 0 
});
s1.addText("Real-World Gen AI Use Cases", { 
    x: 0.5, y: 2.4, w: 9, h: 0.6, 
    fontSize: 40, fontFace: FONT_HEAD, color: C_WHITE, bold: true, margin: 0 
});
s1.addText("from Google Cloud Customers", { 
    x: 0.5, y: 3.0, w: 9, h: 0.5, 
    fontSize: 24, fontFace: FONT_HEAD, color: C_ICE, margin: 0 
});
s1.addShape(pres.shapes.LINE, {
    x: 0.5, y: 3.8, w: 2.0, h: 0, line: { color: C_CORAL, width: 3 }
});
s1.addText([
    {text: "11 Industries", options: {bold: true}},
    {text: "   |   "},
    {text: "6 Agent Types", options: {bold: true}},
    {text: "   |   "},
    {text: "Updated October 2025", options: {bold: true}}
], { x: 0.5, y: 4.2, w: 9, h: 0.4, fontSize: 16, fontFace: FONT_BODY, color: C_ICE, margin: 0 });


// SLIDE 2: Growth
let s2 = pres.addSlide();
s2.background = { color: C_LIGHT_BG };
addSlideTitle(s2, "From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months");

s2.addShape(pres.shapes.RECTANGLE, { x: 1.0, y: 1.8, w: 3.0, h: 2.5, fill: { color: C_WHITE }, shadow: makeShadow() });
s2.addText("101", { x: 1.0, y: 2.2, w: 3.0, h: 0.8, fontSize: 60, fontFace: FONT_HEAD, color: C_NAVY, bold: true, align: "center" });
s2.addText("Use Cases", { x: 1.0, y: 3.0, w: 3.0, h: 0.4, fontSize: 18, fontFace: FONT_BODY, color: C_MUTED_TEXT, align: "center", bold: true });
s2.addText("April 2024\nCloud Next 24", { x: 1.0, y: 3.6, w: 3.0, h: 0.6, fontSize: 14, fontFace: FONT_BODY, color: C_MUTED_TEXT, align: "center" });

s2.addShape(pres.shapes.RIGHT_ARROW, { x: 4.2, y: 2.7, w: 1.6, h: 0.6, fill: { color: C_CORAL } });
s2.addText("10× Growth", { x: 4.2, y: 2.2, w: 1.6, h: 0.4, fontSize: 16, fontFace: FONT_BODY, color: C_CORAL, bold: true, align: "center" });

s2.addShape(pres.shapes.RECTANGLE, { x: 6.0, y: 1.3, w: 3.5, h: 3.5, fill: { color: C_NAVY }, shadow: makeShadow() });
s2.addText("1,001", { x: 6.0, y: 1.9, w: 3.5, h: 1.0, fontSize: 72, fontFace: FONT_HEAD, color: C_CORAL, bold: true, align: "center" });
s2.addText("Use Cases", { x: 6.0, y: 2.9, w: 3.5, h: 0.5, fontSize: 22, fontFace: FONT_BODY, color: C_WHITE, align: "center", bold: true });
s2.addText("October 2025", { x: 6.0, y: 4.0, w: 3.5, h: 0.6, fontSize: 16, fontFace: FONT_BODY, color: C_ICE, align: "center" });


// SLIDE 3: Taxonomy
let s3 = pres.addSlide();
s3.background = { color: C_WHITE };
addSlideTitle(s3, "11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI");

s3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 4.2, h: 4.0, fill: { color: C_LIGHT_BG }, shadow: makeShadow() });
s3.addText("11 Industry Verticals", { x: 0.5, y: 1.2, w: 4.2, h: 0.6, fontSize: 18, fontFace: FONT_HEAD, color: C_WHITE, bold: true, align: "center", fill: { color: C_NAVY } });
const industries = [
    "Automotive & Logistics", "Business & Professional Services", "Financial Services", 
    "Healthcare & Life Sciences", "Hospitality & Travel", "Manufacturing, Industrial & Electronics", 
    "Media, Marketing & Gaming", "Public Sector & Nonprofits", "Retail", 
    "Technology", "Telecommunications"
];
s3.addText(industries.join("\n"), { x: 0.8, y: 1.9, w: 3.6, h: 3.2, fontSize: 13, fontFace: FONT_BODY, color: C_DARK_TEXT, lineSpacing: 22 });

s3.addShape(pres.shapes.MATH_MULTIPLY, { x: 4.85, y: 3.0, w: 0.3, h: 0.3, fill: { color: C_CORAL } });

s3.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 1.2, w: 4.2, h: 4.0, fill: { color: C_LIGHT_BG }, shadow: makeShadow() });
s3.addText("6 Agent Types", { x: 5.3, y: 1.2, w: 4.2, h: 0.6, fontSize: 18, fontFace: FONT_HEAD, color: C_WHITE, bold: true, align: "center", fill: { color: C_NAVY } });

const agents = [
    { title: "Customer", desc: "Conversational assistants, service reduction" },
    { title: "Employee", desc: "Productivity, research, summarization" },
    { title: "Creative", desc: "Asset generation, hyper-personalized ads" },
    { title: "Code", desc: "Enterprise code bases, standards, conventions" },
    { title: "Data", desc: "Filtering, insights across systems" },
    { title: "Security", desc: "Threat analysis, safety monitoring" }
];
let yOff = 1.9;
agents.forEach(a => {
    s3.addText(a.title, { x: 5.6, y: yOff, w: 1.5, h: 0.4, fontSize: 14, fontFace: FONT_BODY, color: C_NAVY, bold: true });
    s3.addText(a.desc, { x: 6.9, y: yOff, w: 2.4, h: 0.4, fontSize: 12, fontFace: FONT_BODY, color: C_MUTED_TEXT });
    yOff += 0.55;
});


// SLIDE 4: Deep Dive Table
let s4 = pres.addSlide();
s4.background = { color: C_LIGHT_BG };
addSlideTitle(s4, "Automotive & Logistics: AI Agents From Cockpit to Curbside");

let tableData = [
    [{ text: "Agent Type", options: { fill: { color: C_NAVY }, color: C_WHITE, bold: true, margin: 0.1 } }, 
     { text: "Organization", options: { fill: { color: C_NAVY }, color: C_WHITE, bold: true, margin: 0.1 } }, 
     { text: "Use Case & Impact", options: { fill: { color: C_NAVY }, color: C_WHITE, bold: true, margin: 0.1 } }],
    ["Customer", "Mercedes-Benz", "MBUX Virtual Assistant via Vertex AI enables natural driver conversations"],
    ["Customer", "LUXGEN", "AI agent on LINE reduced human CS workload by 30%"],
    ["Employee", "Toyota", "AI platform on Google Cloud saved 10,000+ man-hours/year"],
    ["Customer", "UPS Capital", "ML-based DeliveryDefense Address Confidence scores delivery success"],
    ["Code", "Renault Group", "Gemini Code Assist understands EV software code base & standards"]
];
s4.addTable(tableData, { 
    x: 0.5, y: 1.5, w: 9.0, rowH: 0.6,
    colW: [1.5, 2.0, 5.5],
    border: { pt: 1, color: C_ICE },
    fill: { color: C_WHITE },
    fontSize: 14, fontFace: FONT_BODY, color: C_DARK_TEXT,
    valign: "middle"
