s5.background = { color: C_NAVY };
addSlideTitle(s5, "Quantified Impact: 500% ROI, 30% Workload Reduction, 10,000 Hours Saved", true);

let metrics = [
    { stat: "500%", label: "ROI Anticipated", sub: "Mercari reducing employee workloads 20% via AI service" },
    { stat: "30%", label: "Workload Reduction", sub: "LUXGEN cut customer service volume with Vertex AI" },
    { stat: "10,000+", label: "Hours Saved / Year", sub: "Toyota factory AI platform deployed on Google Cloud" },
    { stat: "6,000+", label: "Unique Headlines", sub: "PODS adaptive billboards across NYC in 29 hours" }
];

let mx = 0.4;
metrics.forEach((m, idx) => {
    s5.addShape(pres.shapes.RECTANGLE, { x: mx, y: 1.6, w: 2.1, h: 3.3, fill: { color: C_WHITE }, shadow: makeShadow() });
    s5.addText(m.stat, { x: mx, y: 2.0, w: 2.1, h: 0.8, fontSize: 38, fontFace: FONT_HEAD, color: C_CORAL, bold: true, align: "center" });
    s5.addText(m.label, { x: mx+0.1, y: 2.8, w: 1.9, h: 0.6, fontSize: 14, fontFace: FONT_BODY, color: C_NAVY, bold: true, align: "center" });
    s5.addText(m.sub, { x: mx+0.1, y: 3.5, w: 1.9, h: 1.0, fontSize: 12, fontFace: FONT_BODY, color: C_MUTED_TEXT, align: "center" });
    mx += 2.35;
});


// SLIDE 6: Patterns
