    { title: "Employee Productivity Tools", ex: "Uber, Rivian, Geotab", desc: "Using Gemini for Google Workspace to summarize documents, accelerate research, review legal docs, and filter complex data." },
    { title: "Creative at Scale", ex: "Virgin Voyages, Figma, PODS", desc: "Moving from text to multimodal production: generating hyper-personalized ads, brand-approved assets, and adaptive billboards instantly." }
