    s6.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: py, w: 0.15, h: 1.1, fill: { color: C_CORAL } }); 
    s6.addText(p.title, { x: 0.8, y: py + 0.15, w: 3.5, h: 0.4, fontSize: 18, fontFace: FONT_HEAD, color: C_NAVY, bold: true });
