    { text: "   Conversational assistants and productivity tools form the most common entry points.", options: { color: C_MUTED_TEXT, fontSize: 14, breakLine: true } },

    { text: "3. Measurable ROI is Achievable", options: { bold: true, color: C_NAVY, fontSize: 18, breakLine: true } },
    { text: "   Outcomes like 30% workload reduction and 500% ROI are happening within months.", options: { color: C_MUTED_TEXT, fontSize: 14, breakLine: true } },

    { text: "4. Creative & Code Agents are Emerging Fast", options: { bold: true, color: C_NAVY, fontSize: 18, breakLine: true } },
    { text: "   Multimodal content generation and enterprise coding assist provide rapid value.", options: { color: C_MUTED_TEXT, fontSize: 14, breakLine: true } },

    { text: "5. Accelerating Adoption Pace", options: { bold: true, color: C_NAVY, fontSize: 18, breakLine: true } },
    { text: "   With 10× growth in 18 months, early movers gain compounding strategic advantages.", options: { color: C_MUTED_TEXT, fontSize: 14 } }
], { x: 0.8, y: 1.4, w: 8.4, h: 3.6, fontFace: FONT_BODY, paraSpaceAfter: 8 });

pres.writeFile({ fileName: "/app/output/final_deck.pptx" }).then(() => {
    console.log("PPTX created successfully.");
}).catch(err => {
    console.error("Error creating PPTX:", err);
});

